gvp(){return"\u0644\u0625\u0644\u0647\u0627\u0645 \u0627\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631\u0627\u062a \u0627\u0644\u062a\u064a \u062a\u062f\u0641\u0639 \u0627\u0644\u0639\u0627\u0644\u0645 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645."},
lq(a){return"\u062a\u0639\u0630\u0631 \u062a\u0634\u063a\u064a\u0644 "+a},
