gop(){return"\u062a\u0639\u064a\u064a\u0646 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631*"},
gw6(){return"\u064a\u062c\u0628 \u0623\u0646 \u062a\u062a\u0643\u0648\u0646 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0645\u0646 8 \u0623\u062d\u0631\u0641 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644"},
gph(){return"\u0644\u0642\u062f \u0642\u0631\u0623\u062a \u0648\u0641\u0647\u0645\u062a \u0648\u0648\u0627\u0641\u0642\u062a \u0639\u0644\u0649 Coinetra"},
gvT(){return"\u0627\u062a\u0641\u0627\u0642\u064a\u0629 \u0639\u062f\u0645 \u0627\u0644\u0625\u0641\u0635\u0627\u062d"},
gqD(){return"\u060c \u0648"},
gwV(){return"\u0625\u0634\u0639\u0627\u0631 \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629"},
gpj(){return"\u0627\u0644\u0627\u062a\u0641\u0627\u0642 \u0645\u0637\u0644\u0648\u0628"},
gmJ(){return"\u0625\u0646\u0634\u0627\u0621 \u062d\u0633\u0627\u0628"},
goC(){return"\u0627\u0644\u062e\u0637\u0648\u0629 \u0627\u0644\u0623\u0648\u0644\u0649"},
gtJ(){return"\u0627\u0645\u0644\u0623 \u0627\u0644\u062a\u0641\u0627\u0635\u064a\u0644 \u0627\u0644\u062e\u0627\u0635\u0629 \u0628\u0643 \u0644\u0625\u0646\u0634\u0627\u0621 \u062d\u0633\u0627\u0628 \u0622\u0645\u0646."},
