gqk(){return"\u0935\u094d\u092f\u0935\u0938\u094d\u0925\u093f\u0924 \u0930\u0939\u0928\u0947 \u0914\u0930 \u0905\u0928\u0941\u0915\u0942\u0932\u0928 \u092f\u094b\u0917\u094d\u092f \u092c\u091a\u0924 \u0932\u0915\u094d\u0937\u094d\u092f \u0928\u093f\u0930\u094d\u0927\u093e\u0930\u093f\u0924 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0906\u0938\u093e\u0928\u0940 \u0938\u0947 \u0905\u092a\u0928\u093e \u092a\u0948\u0938\u093e \u091c\u092e\u093e \u0915\u0930\u0947\u0902\u0964"},
god(){return"\u092c\u091a\u0924? \u091c\u093e\u0901\u091a \u0939\u094b \u0930\u0939\u0940 \u0939\u0948?"},
gpT(){return"\u092c\u0947\u0939\u0924\u0930."},
gpU(){return"\u0915\u094c\u0928 \u0915\u0939\u0924\u093e \u0939\u0948 \u0915\u093f \u0906\u092a\u0915\u094b \u090f\u0915 \u092f\u093e \u0926\u0942\u0938\u0930\u0947 \u0915\u094b \u091a\u0941\u0928\u0928\u093e \u0939\u094b\u0917\u093e? Coinetra \u090f\u0915 \u092c\u0948\u0902\u0915 \u0928\u0939\u0940\u0902 \u0939\u0948, \u0932\u0947\u0915\u093f\u0928 \u0939\u092e \u0906\u092a\u0915\u094b \u0909\u0926\u094d\u092f\u094b\u0917-\u0905\u0917\u094d\u0930\u0923\u0940 \u0935\u093e\u0930\u094d\u0937\u093f\u0915 \u092a\u094d\u0930\u0924\u093f\u0936\u0924 \u092f\u0940\u0932\u094d\u0921 (APY), FDIC \u092c\u0940\u092e\u093e \u0915\u0940 \u0938\u0941\u0930\u0915\u094d\u0937\u093e, \u0914\u0930 \u0936\u0941\u0932\u094d\u0915-\u092e\u0941\u0915\u094d\u0924, \u092c\u093f\u0928\u093e-\u0938\u094d\u091f\u094d\u0930\u093f\u0902\u0917\u094d\u0938-\u0938\u0902\u0932\u0917\u094d\u0928 \u091a\u0947\u0915\u093f\u0902\u0917 \u0938\u0941\u0935\u093f\u0927\u093e\u0913\u0902 \u0915\u0940 \u090f\u0915 \u092a\u0942\u0930\u0940 \u0936\u094d\u0930\u0943\u0902\u0916\u0932\u093e \u092a\u094d\u0930\u0926\u093e\u0928 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u094d\u0930\u094b\u0917\u094d\u0930\u093e\u092e \u092c\u0948\u0902\u0915\u094b\u0902 \u0915\u0947 \u0938\u093e\u0925 \u0915\u093e\u092e \u0915\u0930\u0924\u0947 \u0939\u0948\u0902 - \u0938\u092d\u0940 \u0915\u094b \u090f\u0915 \u0932\u0947\u092c\u0932-\u0921\u093f\u092b\u093c\u093e\u0907\u0902\u0917 \u092a\u0948\u0915\u0947\u091c \u092e\u0947\u0902 \u0932\u092a\u0947\u091f\u093e \u091c\u093e\u0924\u093e \u0939\u0948 \u091c\u093f\u0938\u0947 \u0939\u092e \u0915\u0948\u0936 \u0905\u0915\u093e\u0909\u0902\u091f \u0915\u0939\u0924\u0947 \u0939\u0948\u0902\u0964"},
gmy(){return"\u0938\u0930\u094d\u0935\u0936\u094d\u0930\u0947\u0937\u094d\u0920 \u0928\u0915\u0926 \u092a\u094d\u0930\u092c\u0902\u0927\u0928 \u0916\u093e\u0924\u093e, 2023-25 \xb3"},
gnR(){return"\u0935\u093f\u0936\u094d\u0935\u0938\u0928\u0940\u092f \u0917\u094d\u0930\u093e\u0939\u0915 \xb9"},
