gxX(){return"\u0920\u0940\u0915 \u0924\u092c \u0924\u0915 \u091c\u092c \u0924\u0915 \u0906\u092a\u0915\u094b \u0907\u0938\u0915\u0940 \u0906\u0935\u0936\u094d\u092f\u0915\u0924\u093e \u0928 \u0939\u094b\u0964"},
gql(){return"\u092e\u0941\u092b\u093c\u094d\u0924 24/7 \u0924\u0924\u094d\u0915\u093e\u0932 \u0928\u093f\u0915\u093e\u0938\u0940 \u0915\u0947 \u0938\u093e\u0925 \u092a\u094d\u0930\u094b\u0917\u094d\u0930\u093e\u092e \u092c\u0948\u0902\u0915\u094b\u0902 \u0938\u0947 \u0909\u0926\u094d\u092f\u094b\u0917-\u0905\u0917\u094d\u0930\u0923\u0940 APY \u0905\u0930\u094d\u091c\u093f\u0924 \u0915\u0930\u0947\u0902\u0964"},
gzP(){return"\u0936\u0942\u0928\u094d\u092f \u0916\u093e\u0924\u093e \u0936\u0941\u0932\u094d\u0915"},
gvQ(){return"4.00% APY \u0905\u0930\u094d\u091c\u093f\u0924 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u094b\u0908 \u0928\u094d\u092f\u0942\u0928\u0924\u092e \u092f\u093e \u0905\u0927\u093f\u0915\u0924\u092e \u0936\u0947\u0937 \u0930\u093e\u0936\u093f \u0928\u0939\u0940\u0902"},
